mapper.select:
select tradeid,finprodid,channelname,feename,mdate,settledate,sum(theoryint) theoryint,effectStatus,sum(tradeamt) tradeamt,finprodMarketId from (SELECT T1.TOTLE_TRADE_ID tradeId, T1.FINPROD_ID finprodId, T4.FINPROD_MARKET_ID finprodMarketId, NVL(T4.FINPROD_ABBR, T4.FINPROD_NAME) channelName, '${SINGLE_FEE_TYPE_03}' feeName, T1.MDATE, T1.SETTLE_DATE settleDate, T3.THEORY_INT theoryInt, T1.TRADE_AMT tradeAmt, decode(T1.IS_CANCEL,'Y','03','01') effectStatus FROM TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T3 ON T1.TRADE_ID = T3.TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID WHERE T1.BUSI_TYPE = #{BT_18} AND T1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03} AND T1.CHL_ID IS NOT NULL and T1.TRADE_STATUS = #{TRADE_STATUS01}
AND (T4.FINPROD_MARKET_ID IN (
null) OR T4.FINPROD_MARKET_ID in (
#{item}
) )
AND T1.TRADE_ID LIKE CONCAT('%',CONCAT(#{bizCode},'%'))
AND T1.SETTLE_DATE >= TO_DATE(#{payDateStart}, 'yyyy-MM-dd')
AND TO_DATE(#{payDateEnd}, 'yyyy-MM-dd') >= T1.SETTLE_DATE
) group by tradeid,finprodid,channelname,feename,mdate,settledate,effectStatus,finprodMarketId

SELECT FINPROD_ID, VDATE, sum(tradeAmt) tradeAmt, CCY
from (
         SELECT FEE.FINPROD_ID,
                CASE
                    WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NOT NULL AND T1.MDATE > T2.MDATE THEN T1.MDATE
                    WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NOT NULL AND T2.MDATE > T1.MDATE THEN T2.MDATE
                    WHEN T1.MDATE IS NOT NULL AND T2.MDATE IS NULL THEN T1.MDATE
                    WHEN T2.MDATE IS NOT NULL AND T1.MDATE IS NULL THEN T2.MDATE
                    ELSE T3.VDATE END    VDATE,
                FEE.TDY_UNPAID_INTINCEXP tradeAmt,
                T3.CCY
         FROM BOK_POSITION_PRDFEE FEE
                  LEFT JOIN TRD_PRODUCT_DEAL T1
                            ON FEE.FINPROD_ID = T1.FINPROD_ID AND T1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
                                AND T1.MDATE < TO_DATE(#{mdate}, 'yyyy-MM-dd') and
                               t1.TRADE_STATUS = #{TRADE_STATUS_01} and t1.IS_CANCEL = #{N}
                  LEFT JOIN WFL_TRD_PRODUCT_DEAL T2
                            ON FEE.FINPROD_ID = T2.FINPROD_ID AND T2.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
                                AND T2.MDATE < TO_DATE(#{mdate}, 'yyyy-MM-dd') and
                               t2.TRADE_STATUS = #{TRADE_STATUS_01} and t2.IS_CANCEL = #{N}
                  LEFT JOIN FIN_PRODUCT T3 ON FEE.CHL_ID = T3.FINPROD_ID
                  LEFT JOIN FIN_PRODUCT_ADD fpa ON fee.FINPROD_ID = fpa.FINPROD_ID
         WHERE FEE.FEE_TYPE IN (#{C12}, #{C13}, #{C14}, #{B09})
           AND (FEE.FINPROD_ID = #{ptlId} OR fpa.PORTFOLIO_ID = #{ptlId})
           AND FEE.CHL_ID = #{chlId}
           AND FEE.TDY_UNPAID_INTINCEXP > 0
           AND FEE.CDATE = TO_DATE(#{mdate}, 'yyyy-MM-dd') - 1
           AND NOT EXISTS(SELECT 1
                          FROM TRD_PRODUCT_DEAL TT1
                          WHERE FEE.FINPROD_ID = TT1.FINPROD_ID
                            AND TT1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
                            and TT1.TRADE_STATUS = #{TRADE_STATUS_01}
                            and TT1.IS_CANCEL = #{N}
                            AND TT1.MDATE < TO_DATE(#{mdate}, 'yyyy-MM-dd')
                            AND TT1.MDATE > T1.MDATE
             )
           AND NOT EXISTS(SELECT 1
                          FROM WFL_TRD_PRODUCT_DEAL TT1
                          WHERE FEE.FINPROD_ID = TT1.FINPROD_ID
                            AND TT1.FINPROD_TYPE2 = #{SINGLE_FEE_TYPE_03}
                            and TT1.TRADE_STATUS = #{TRADE_STATUS_01}
                            and TT1.IS_CANCEL = #{N}
                            AND TT1.MDATE < TO_DATE(#{mdate}, 'yyyy-MM-dd')
                            AND TT1.MDATE > T2.MDATE
             )
     )
group by FINPROD_ID, VDATE, CCY

SELECT deal.TOTLE_TRADE_ID
FROM TRD_PRODUCT_DEAL deal
         LEFT JOIN TRD_PRODUCT_DEAL_ADD t on deal.TRADE_ID = t.TRADE_ID
WHERE deal.MDATE = #{mdate, jdbcType=DATE}
  AND deal.FINPROD_ID = #{finprodId}
  and deal.TRADE_STATUS = #{TRADE_STATUS_01}
  and deal.IS_CANCEL = #{N}
  and t.PORTFOLIO_ID = #{portfolioId}
UNION ALL
SELECT wfl.TOTLE_TRADE_ID || '流程中'
FROM WFL_TRD_PRODUCT_DEAL wfl
         LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wfladd on wfl.TRADE_ID = wfladd.TRADE_ID
WHERE wfl.MDATE = #{mdate, jdbcType=DATE}
  AND wfl.FINPROD_ID = #{finprodId}
  and wfl.TRADE_STATUS = #{TRADE_STATUS_01}
  and wfl.IS_CANCEL = #{N}
  and wfladd.PORTFOLIO_ID = #{portfolioId}

SELECT FINPROD_MARKET_ID id, nvl(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object/*通道代码*/
FROM FIN_PRODUCT

    FINPROD_TYPE2 = #{F28}
    AND IS_CHL = #{Y}

        AND (FINPROD_ID LIKE CONCAT('%',CONCAT(#{search},'%'))
        OR FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{search},'%'))
        OR FINPROD_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))


        AND FINPROD_MARKET_ID = #{initValue}


WHERE (TRADE_ID IN


        null) OR TRADE_ID in (

    #{item.tradeId}

)
